@router.get("/documents/signing-session/verify")
async def verify_signing_session_token(
    session_token: str = Query(...),
    signer_id: str = Query(...),
    db: AsyncSession = Depends(get_db)
):
    stmt = select(SigningSessionToken).where(
        SigningSessionToken.token == session_token,
        SigningSessionToken.expires_at > datetime.utcnow()
    )
    token_record = await db.scalar(stmt)
    if not token_record or token_record.signer_id != signer_id:
        raise HTTPException(status_code=400, detail="Invalid signing session or signer mismatch")

    contract = await db.scalar(
        select(SignableDocument).where(SignableDocument.signer_id == token_record.signer_id)
    )
    if not contract:
        raise HTTPException(status_code=404, detail="Document not found for specified signer")

    return {
        "document_id": contract.id,
        "title": contract.title,
        "pdf_download_url": contract.s3_pre_signed_url,
        "signature_fields": contract.required_fields
    }
